package br.com.erp;
import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
class TreasuryTest extends ApiTestSupport {
 private String branch(String token)throws Exception{return getApi("/api/v1/branches",token,200).get("items").get(0).get("id").asText();}
 private Map<String,Object> account(String branch,String code){return Map.of("requestId",UUID.randomUUID(),"branchId",branch,"code",code,"name","Conta "+code,"kind","BANK");}
 private String create(String token,String code)throws Exception{return postApi("/api/v1/treasury/accounts",token,account(branch(token),code),201).get("id").asText();}
 private Map<String,Object> movement(UUID request,String source,String destination,String amount){var m=new HashMap<String,Object>();m.put("requestId",request);m.put("sourceId",source);m.put("destinationId",destination);m.put("amount",amount);m.put("note","Lançamento interno de teste");return m;}
 private void move(String token,String from,String to,String amount,int status)throws Exception{postApi("/api/v1/treasury/movements",token,movement(UUID.randomUUID(),from,to,amount),status);}
 private String balance(String token,String id)throws Exception{return getApi("/api/v1/treasury/accounts/"+id,token,200).get("balance").asText();}
 @Test void accountsStartAtZeroAndCreationIsIdempotent()throws Exception{String t=token(company);var input=account(branch(t),"bank");var a=postApi("/api/v1/treasury/accounts",t,input,201);assertEquals("BANK",a.get("code").asText());assertEquals("0.00",a.get("balance").asText());assertEquals(a,postApi("/api/v1/treasury/accounts",t,input,201));var changed=new HashMap<>(input);changed.put("name","Alterado");postApi("/api/v1/treasury/accounts",t,changed,409);postApi("/api/v1/treasury/accounts",t,account(branch(t),"BANK"),409);}
 @Test void transferBalancesAndEntriesAreAtomicAndReplaySafe()throws Exception{String t=token(company),a=create(t,"A"),b=create(t,"B");move(t,null,a,"100.00",200);var input=movement(UUID.randomUUID(),a,b,"40.00");var op=postApi("/api/v1/treasury/movements",t,input,200);input.put("amount","40.0");assertEquals(op,postApi("/api/v1/treasury/movements",t,input,200));assertEquals("60.00",balance(t,a));assertEquals("40.00",balance(t,b));assertEquals(2,getApi("/api/v1/treasury/accounts/"+a+"/entries",t,200).get("total").asInt());input.put("amount","41.00");postApi("/api/v1/treasury/movements",t,input,409);move(t,a,b,"61",409);assertEquals("40.00",balance(t,b));move(t,a,null,"60",200);assertEquals("0.00",balance(t,a));}
 @Test void invalidAmountsAndAccountsDoNotChangeBalances()throws Exception{String t=token(company),a=create(t,"A");move(t,null,a,"0",400);move(t,null,a,"1.001",400);move(t,null,null,"1",400);move(t,a,a,"1",400);move(t,null,UUID.randomUUID().toString(),"1",404);assertEquals("0.00",balance(t,a));}
 @Test void monetaryOverflowRollsBack()throws Exception{String t=token(company),a=create(t,"A");move(t,null,a,"99999999999999999.99",200);move(t,null,a,"0.01",409);assertEquals("99999999999999999.99",balance(t,a));assertEquals(1,getApi("/api/v1/treasury/accounts/"+a+"/entries",t,200).get("total").asInt());}
 @Test void tenantsAndPermissionsAreEnforced()throws Exception{String t=token(company),a=create(t,"A"),other="other-"+UUID.randomUUID();provisioning.create("Outra",other,"Admin","admin@example.com",password);getApi("/api/v1/treasury/accounts/"+a,token(other),404);db.update("DELETE FROM user_permission WHERE tenant_id=? AND permission='treasury:move'",tenant);move(t,null,a,"10",403);assertEquals("0.00",balance(t,a));}
 @Test void bothTransferBranchesAndPaginationAreScoped()throws Exception{String t=token(company),a=create(t,"A");var b=postApi("/api/v1/branches",t,Map.of("code","OTHER","name","Outra filial"),201);String bId=b.get("id").asText(),bank=postApi("/api/v1/treasury/accounts",t,account(bId,"B"),201).get("id").asText();db.update("UPDATE app_user SET all_branches=FALSE WHERE tenant_id=?",tenant);db.update("INSERT INTO user_branch_access(tenant_id,user_id,branch_id) SELECT tenant_id,id,? FROM app_user WHERE tenant_id=?",UUID.fromString(branchIdFor(a)),tenant);assertEquals(1,getApi("/api/v1/treasury/accounts",t,200).get("total").asInt());getApi("/api/v1/treasury/accounts/"+bank+"/entries",t,404);move(t,null,a,"10",200);move(t,a,bank,"5",404);assertEquals("10.00",balance(t,a));}
 private String branchIdFor(String id){return db.queryForObject("SELECT branch_id FROM treasury_account WHERE id=?",UUID.class,UUID.fromString(id)).toString();}
 @Test void concurrentDebitsCannotOverdraw()throws Exception{String t=token(company),a=create(t,"A");move(t,null,a,"100",200);try(var pool=Executors.newFixedThreadPool(2)){var gate=new CountDownLatch(1);var calls=new ArrayList<Future<Integer>>();for(int i=0;i<2;i++)calls.add(pool.submit(()->{gate.await();return status(t,movement(UUID.randomUUID(),a,null,"80"));}));gate.countDown();var statuses=new ArrayList<Integer>();for(var f:calls)statuses.add(f.get(20,TimeUnit.SECONDS));Collections.sort(statuses);assertEquals(List.of(200,409),statuses);}assertEquals("20.00",balance(t,a));}
 @Test void concurrentDuplicateProducesOneEntry()throws Exception{String t=token(company),a=create(t,"A");var input=movement(UUID.randomUUID(),null,a,"10");try(var pool=Executors.newFixedThreadPool(2)){var gate=new CountDownLatch(1);var calls=new ArrayList<Future<Integer>>();for(int i=0;i<2;i++)calls.add(pool.submit(()->{gate.await();return status(t,input);}));gate.countDown();for(var f:calls)assertEquals(200,f.get(20,TimeUnit.SECONDS));}assertEquals("10.00",balance(t,a));assertEquals(1,getApi("/api/v1/treasury/accounts/"+a+"/entries",t,200).get("total").asInt());}
 private int status(String token,Object input)throws Exception{return http.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/v1/treasury/movements").header("Authorization","Bearer "+token).contentType("application/json").content(json.writeValueAsString(input))).andReturn().getResponse().getStatus();}
}
